<?php
require_once __DIR__.'/../includes/auth.php'; require_role('student');$q=trim($_GET['q']??'');$s=$pdo->prepare("SELECT e.*,l.name lab,c.name category FROM equipment e LEFT JOIN laboratories l ON l.id=e.laboratory_id LEFT JOIN equipment_categories c ON c.id=e.category_id WHERE e.name LIKE ? OR e.equipment_code LIKE ? ORDER BY e.name");$s->execute(['%'.$q.'%','%'.$q.'%']);$rows=$s->fetchAll();page_header('Browse Equipment','student');?>
<form class="d-flex gap-2 mb-4"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search equipment"><button class="btn btn-primary">Search</button></form><div class="equipment-grid"><?php foreach($rows as $r):?><div class="equipment-card"><div class="equipment-image">⚙</div><h3><?=e($r['name'])?></h3><p class="muted"><?=e($r['equipment_code'])?> · <?=e($r['category']??'General')?></p><p><?=e($r['description'])?></p><p class="muted">Lab: <?=e($r['lab'])?></p><p>Available: <b><?=$r['available_quantity']?></b></p><?=status_badge($r['condition_status']==='Under Maintenance'?'Under Maintenance':($r['available_quantity']>0?'Available':'Fully Booked'))?><div class="mt-3"><a class="btn btn-primary w-100" href="book-equipment.php?id=<?=$r['id']?>" <?=$r['available_quantity']<1||$r['condition_status']==='Under Maintenance'?'aria-disabled="true"':''?>>Book now</a></div></div><?php endforeach?></div><?php if(!$rows):?><div class="empty">No equipment matched your search.</div><?php endif?><?php page_footer();?>
